from leetcode.problems.p1878_biggest_3_rhombus_sums import Solution


def test_example1():
    grid = [
        [3, 4, 5, 1, 3],
        [3, 3, 4, 2, 3],
        [20, 30, 200, 40, 10],
        [1, 5, 5, 4, 1],
        [4, 3, 2, 2, 5],
    ]
    actual = Solution().getBiggestThree(grid)
    expected = [228, 216, 211]
    assert actual == expected, ""


def test_example2():
    grid = [
        [1, 2, 3],
        [4, 5, 6],
        [7, 8, 9],
    ]
    actual = Solution().getBiggestThree(grid)
    expected = [20, 9, 8]
    assert actual == expected, ""


def test_example3():
    grid = [[7, 7, 7]]
    actual = Solution().getBiggestThree(grid)
    expected = [7]
    assert actual == expected, ""


